/**
 * DescriptionList. Things and their values: order details, account
 * settings, a device's specs, the status of a system at a glance.
 *
 * `plain` sets the terms as machine labels over their values, with the
 * library's one separator between rows. `screen` puts the whole list on a
 * dark screen, the values in the readout face: the glance list on a phone's
 * home screen, a status panel on a dashboard.
 *
 * It's a real description list: each term and its value are read together.
 */
import type { ReactNode } from "react";
import "../scope/scope.css";
import "./description-list.css";

export interface DescriptionListItem {
  /** What it is: "Battery", "Order number". */
  term: ReactNode;
  /** Its value. */
  detail: ReactNode;
  /** A small glyph before the term. Decorative: the term says what it is. */
  icon?: ReactNode;
}

export interface DescriptionListProps {
  items: readonly DescriptionListItem[];
  /** `plain` (default) on the page; `screen` on a dark screen, values in the readout face. */
  variant?: "plain" | "screen";
  /** `stacked` (default) puts each value under its term; `inline` sets them side by side. */
  layout?: "stacked" | "inline";
  /** With `variant="screen"`: `emissive` (default) is dark; `reflective` is the paper-coloured glass of a pocket calculator, printed in ink. */
  screen?: "emissive" | "reflective";
}

export function DescriptionList({ items, variant = "plain", layout = "stacked", screen = "emissive" }: DescriptionListProps) {
  return (
    <dl
      className="echo-description-list"
      data-variant={variant}
      data-layout={layout}
      data-echo-screen={variant === "screen" && screen === "reflective" ? "reflective" : undefined}
    >
      {items.map((item, i) => (
        <div key={i} className="echo-description-list__row">
          <dt className="echo-description-list__term">
            {item.icon ? (
              <span className="echo-description-list__icon" aria-hidden="true">
                {item.icon}
              </span>
            ) : null}
            {item.term}
          </dt>
          <dd className="echo-description-list__detail">{item.detail}</dd>
        </div>
      ))}
    </dl>
  );
}

/**
 * DescriptionList. Terms in the machine voice, values in body text or, on a
 * screen, in the readout face; the one separator between rows. Composes
 * var(--echo-*) — no hex literals; the only fixed values are the key light.
 */
.echo-description-list {
  display: grid;
  margin: 0;
  min-inline-size: 0;
}

.echo-description-list__row {
  display: grid;
  gap: var(--echo-space-2);
  padding-block: var(--echo-space-5);
  min-inline-size: 0;
}
/* The one separator: a dark groove over a faint lip. */
.echo-description-list__row + .echo-description-list__row {
  border-block-start: var(--echo-border-hairline, 1px) solid var(--echo-seam);
  box-shadow: inset 0 1px 0 rgb(255 255 255 / calc(0.04 * var(--echo-gloss, 1)));
}
.echo-description-list[data-layout="inline"] .echo-description-list__row {
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: baseline;
  gap: var(--echo-space-6);
}

.echo-description-list__term {
  display: flex;
  align-items: center;
  gap: var(--echo-space-3);
  min-inline-size: 0;
  font-family: var(--echo-font-machine, ui-sans-serif, system-ui, sans-serif);
  font-size: var(--echo-text-3xs);
  font-weight: var(--echo-weight-bold, 700);
  letter-spacing: var(--echo-tracking-wider, 0.12em);
  line-height: var(--echo-leading-tight, 1.25);
  text-transform: uppercase;
  color: var(--echo-text-dim);
  overflow-wrap: anywhere;
}
.echo-description-list__icon {
  display: inline-flex;
  flex: none;
  inline-size: var(--echo-icon-sm, 14px);
  block-size: var(--echo-icon-sm, 14px);
}
.echo-description-list__icon > svg {
  inline-size: 100%;
  block-size: 100%;
}

.echo-description-list__detail {
  margin: 0;
  min-inline-size: 0;
  font-family: var(--echo-font-sans, ui-sans-serif, system-ui, sans-serif);
  font-size: var(--echo-text-md);
  line-height: var(--echo-leading-snug, 1.4);
  color: var(--echo-text);
  overflow-wrap: anywhere;
}
.echo-description-list[data-layout="inline"] .echo-description-list__detail {
  text-align: end;
}

/* screen: the whole list on a dark screen, the values in the readout face. */
.echo-description-list[data-variant="screen"] {
  padding: var(--echo-space-3) var(--echo-space-8);
  border-radius: var(--echo-radius-lg);
  background: var(--echo-drawn-glass, linear-gradient(160deg, var(--echo-well) 0%, var(--echo-lcd) 100%));
  box-shadow: var(
    --echo-shadow-well-screen,
    inset 0 2px 6px color-mix(in oklab, var(--echo-cast-ink, black) calc(0.8 * var(--echo-shade, 1) * 100%), transparent),
    inset 0 -1px 0 rgb(255 255 255 / calc(0.05 * var(--echo-gloss, 1))),
    inset 0 0 0 var(--echo-line-width, 0px) var(--echo-line, transparent)
  );
}
.echo-description-list[data-variant="screen"] .echo-description-list__row + .echo-description-list__row {
  border-block-start-color: color-mix(in oklab, var(--echo-text) 8%, transparent);
  box-shadow: none;
}
.echo-description-list[data-variant="screen"] .echo-description-list__detail {
  font-family: var(--echo-font-lcd, ui-monospace, SFMono-Regular, Menlo, monospace);
  font-size: var(--echo-text-lg);
  font-variant-numeric: tabular-nums;
  line-height: var(--echo-leading-none, 1);
}

@media (forced-colors: active) {
  .echo-description-list[data-variant="screen"] {
    border: var(--echo-border-hairline, 1px) solid CanvasText;
  }
  .echo-description-list__row + .echo-description-list__row {
    border-block-start-color: CanvasText;
  }
}
